import { tags } from "typia";

/**
 * Standard pagination metadata included in paginated responses.
 *
 * This DTO provides information about the current page, total pages, total
 * items, and items per page to enable client-side pagination controls and user
 * awareness of result set size.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPagination = {
  /**
   * Current page number (1-indexed). The page of results that is currently
   * being displayed.
   */
  page: number & tags.Type<"int32">;

  /**
   * Number of records per page. How many items are included in each page of
   * results.
   */
  limit: number & tags.Type<"int32">;

  /**
   * Total number of records across all pages. Complete count of all matching
   * records without pagination.
   */
  total: number & tags.Type<"int32">;

  /**
   * Total number of pages available. Calculated from total records divided by
   * limit per page. Helps determine if there are more pages to retrieve.
   */
  total_pages: number & tags.Type<"int32">;
};
